def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous non-background bars on the four borders.
    runs = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, lo = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - lo >= 2:
                runs.append(("h", r, lo, c, color))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                runs.append(("v", c, lo, r, color))

    bar_cells = set()
    for axis, fixed, lo, hi, _ in runs:
        if axis == "h":
            bar_cells.update((fixed, c) for c in range(lo, hi))
        else:
            bar_cells.update((r, fixed) for r in range(lo, hi))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]
    if not runs or not markers:
        return out
    marker = Counter(color for _, _, color in markers).most_common(1)[0][0]

    # Each pair of equal bars on opposing borders uses sparse markers
    # projected onto the bar's along-edge coordinate to select ray origins.
    groups = {}
    for run in runs:
        axis, fixed, lo, hi, color = run
        groups.setdefault((axis, hi - lo, color), []).append(run)

    selected = []
    for (axis, length, _), group in groups.items():
        fixeds = {run[1] for run in group}
        opposite_edges = ({0, h - 1} if axis == "h" else {0, w - 1})
        if not opposite_edges.issubset(fixeds):
            continue
        offsets = set()
        for _, _, lo, hi, _ in group:
            for r, c, _ in markers:
                pos = c if axis == "h" else r
                if lo <= pos < hi:
                    offsets.add(pos - lo)
        if not offsets:
            offsets = set(range(length))
        for run in group:
            for offset in offsets:
